<?php require __DIR__.'/config/bootstrap.php';$q=trim($_GET['q']??'');$title='Search · PlayGramBlog';require __DIR__.'/includes/header.php';?><h1>Search</h1><form class="form"><input name="q" value="<?=e($q)?>" placeholder="Search posts, categories and tags"><button>Search</button></form><?php if($q!==''){$like='%'.$q.'%';$st=db()->prepare("SELECT DISTINCT p.*,c.name category FROM posts p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN post_tags pt ON pt.post_id=p.id LEFT JOIN tags t ON t.id=pt.tag_id WHERE p.status='published' AND (p.title LIKE ? OR p.content LIKE ? OR c.name LIKE ? OR t.name LIKE ?) ORDER BY p.published_at DESC");$st->execute([$like,$like,$like,$like]);$rows=$st->fetchAll();echo '<h2>Results for “'.e($q).'”</h2><div class="grid">';foreach($rows as $p)echo '<article class="card"><div class="pad"><h3><a href="post.php?slug='.e($p['slug']).'">'.e($p['title']).'</a></h3><p>'.e(excerpt($p['content'])).'</p></div></article>';echo '</div>';if(!$rows)echo '<p>No search results.</p>';}require __DIR__.'/includes/footer.php';